parameters.content:
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Helvetica', 'Arial', sans-serif;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
}

#root {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
}

.calculator {
  width: 100%;
  max-width: 400px;
  background: #1c1c1c;
  border-radius: 20px;
  padding: 20px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}

.calculator-display {
  background: #1c1c1c;
  color: white;
  font-size: 3rem;
  text-align: right;
  padding: 30px 20px;
  border-radius: 10px;
  margin-bottom: 20px;
  min-height: 100px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  overflow: hidden;
  word-wrap: break-word;
  word-break: break-all;
}

.calculator-keypad {
  display: grid;
  grid-template-columns: 3fr 1fr;
  gap: 10px;
}

.input-keys {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.function-keys {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.digit-keys {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.operator-keys {
  display: grid;
  grid-template-columns: 1fr;
  gap: 10px;
}

.calculator-key {
  background: #505050;
  border: none;
  border-radius: 50%;
  color: white;
  font-size: 1.5rem;
  font-weight: 400;
  height: 70px;
  cursor: pointer;
  transition: all 0.1s ease;
  display: flex;
  align-items: center;
  justify-content: center;
}

.calculator-key:hover {
  filter: brightness(1.2);
}

.calculator-key:active {
  filter: brightness(0.9);
  transform: scale(0.95);
}

.key-clear,
.key-sign,
.key-percent {
  background: #a6a6a6;
  color: #1c1c1c;
  font-weight: 500;
}

.key-0 {
  grid-column: 1 / 3;
  border-radius: 35px;
  justify-content: flex-start;
  padding-left: 30px;
}

.operator-keys .calculator-key {
  background: #ff9f0a;
}

.operator-keys .calculator-key:hover {
  background: #ffb340;
}

@media (max-width: 480px) {
  .calculator {
    max-width: 100%;
  }

  .calculator-display {
    font-size: 2.5rem;
    padding: 20px 15px;
    min-height: 80px;
  }

  .calculator-key {
    height: 60px;
    font-size: 1.3rem;
  }

  .key-0 {
    padding-left: 25px;
  }
}

@media (max-width: 360px) {
  .calculator-key {
    height: 50px;
    font-size: 1.2rem;
  }

  .calculator-display {
    font-size: 2rem;
  }
}
